using System;
using UnityEngine;

namespace TactileWars.Battle
{
    /// <summary>An enemy base deployment for the shared lane map: enemy squads and defenses spawned at battle start
    /// by BattleSetup (replacing the handcrafted deployment in Battle.unity). Generated by the editor
    /// ProgressionBuilder from seeds; positions use prop free sockets of the lane so props never overlap.</summary>
    [CreateAssetMenu(menuName = "TactileWars/Base Layout Data")]
    public class BaseLayoutData : ScriptableObject
    {
        public int seed;
        public EnemySquadPlacement[] squads = Array.Empty<EnemySquadPlacement>();
        public DefensePlacementData[] defenses = Array.Empty<DefensePlacementData>();
    }

    [Serializable]
    public struct EnemySquadPlacement
    {
        public Vector3 position;
        public bool advance;
        public int count;
        public int seed;
    }

    [Serializable]
    public struct DefensePlacementData
    {
        [Tooltip("DefenseCatalog id: turret, mine, tank, cannon, bunker.")] public string defenseId;
        public Vector3 position;
        public float yaw;
        [Tooltip("Tank only: patrol end points.")] public Vector3 patrolA, patrolB;
    }
}
